using System;

namespace Realmkeeper.Domain.Identifiers
{
    /// <summary>
    /// Stable, GUID-based identifier. Never derived from display names.
    /// Generated by <see cref="Realmkeeper.Domain.Randomness.DeterministicGuid"/> during
    /// world generation/simulation so identical seeds reproduce identical identifiers.
    /// </summary>
    public readonly struct MemoryId : IEquatable<MemoryId>, IComparable<MemoryId>
    {
        public Guid Value { get; }

        public MemoryId(Guid value)
        {
            Value = value;
        }

        public static MemoryId Empty => default;

        public bool IsEmpty => Value == Guid.Empty;

        /// <summary>Creates a random (non-deterministic) identifier. Use only outside simulation/generation.</summary>
        public static MemoryId NewRandom() => new MemoryId(Guid.NewGuid());

        public static MemoryId Parse(string text) => new MemoryId(Guid.Parse(text));

        public static bool TryParse(string text, out MemoryId id)
        {
            if (Guid.TryParse(text, out var guid))
            {
                id = new MemoryId(guid);
                return true;
            }

            id = Empty;
            return false;
        }

        public bool Equals(MemoryId other) => Value.Equals(other.Value);

        public override bool Equals(object obj) => obj is MemoryId other && Equals(other);

        public override int GetHashCode() => Value.GetHashCode();

        public int CompareTo(MemoryId other) => Value.CompareTo(other.Value);

        public override string ToString() => Value.ToString("D");

        public static bool operator ==(MemoryId left, MemoryId right) => left.Equals(right);

        public static bool operator !=(MemoryId left, MemoryId right) => !left.Equals(right);
    }
}
